import{_ as e,o as s,c as t,a3 as i}from"./chunks/framework.BNNhFWPR.js";const k=JSON.parse('{"title":"Addons","description":"Create addons that share assets or extend the engine with a native C++ library.","frontmatter":{"id":"addons","title":"Addons","order":15,"description":"Create addons that share assets or extend the engine with a native C++ library.","editUrl":"https://github.com/ATMO-Engine/atmo/edit/main/docs/en/manual/addons.md"},"headers":[],"relativePath":"manual/addons.md","filePath":"en/manual/addons.md"}'),d={name:"manual/addons.md"};function n(o,a,r,l,h,p){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="addons" tabindex="-1">Addons <a class="header-anchor" href="#addons" aria-label="Permalink to &quot;Addons&quot;">​</a></h1><p>An addon is a folder of a project that holds assets, or a native library that extends the engine with C++ code.</p><h2 id="create" tabindex="-1">Create an addon <a class="header-anchor" href="#create" aria-label="Permalink to &quot;Create an addon {#create}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atmo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/my-game</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --new-addon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;My Addon&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atmo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/my-game</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --new-addon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;My Addon&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> library</span></span></code></pre></div><p>The addon is created in the <code>addons</code> folder of the project, enabled, and added to the <a href="/latest/manual/project-settings#addons" class="atmo-ref atmo-ref--page" data-preview="Every project setting, its default value and what it changes.">project settings</a>. Characters other than letters, digits, <code>_</code> and <code>-</code> are replaced by <code>_</code> in the name of its folder:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>addons/My_Addon/</span></span>
<span class="line"><span>├── addon.json</span></span>
<span class="line"><span>├── assets/              # assets addon</span></span>
<span class="line"><span>├── src/My_Addon.cpp     # library addon</span></span>
<span class="line"><span>└── xmake.lua            # library addon</span></span></code></pre></div><h2 id="manifest" tabindex="-1">The manifest <a class="header-anchor" href="#manifest" aria-label="Permalink to &quot;The manifest {#manifest}&quot;">​</a></h2><p><code>addon.json</code> describes the addon. Its fields are those of <a href="/latest/api/cpp/class/atmo-addon-addonheader" class="atmo-ref atmo-ref--symbol"><code>AddonHeader</code></a>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>Displayed name</td></tr><tr><td><code>internal_name</code></td><td>Name of the folder and of the library</td></tr><tr><td><code>version</code></td><td>Version of the addon</td></tr><tr><td><code>atmo_version</code></td><td>Version of the engine the addon is made for. It must be exactly that of the engine.</td></tr><tr><td><code>license_title</code></td><td>License</td></tr><tr><td><code>authors</code></td><td>List of authors</td></tr><tr><td><code>website</code></td><td>Website</td></tr><tr><td><code>source_link</code></td><td>Where the source code is</td></tr><tr><td><code>has_library</code></td><td>Whether the addon has a native library to load</td></tr></tbody></table><h2 id="enable" tabindex="-1">Enable an addon <a class="header-anchor" href="#enable" aria-label="Permalink to &quot;Enable an addon {#enable}&quot;">​</a></h2><p>Addons are in the <code>addons</code> section of <code>.atmo/project_settings.json</code>, with their path and whether they are enabled:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;addons&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;addons&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;project://addons/My_Addon&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p>The project settings window has a checkbox for each of them. To install an addon made elsewhere, copy its folder into <code>addons</code> and add it there. Addons are loaded when the project is opened or the game starts.</p><h2 id="assets" tabindex="-1">Use the assets <a class="header-anchor" href="#assets" aria-label="Permalink to &quot;Use the assets {#assets}&quot;">​</a></h2><p>The files of an addon are files of the project. They are available even when the addon is disabled:</p><div class="language-luau vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">luau</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">this:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setMaterial</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;project://addons/My_Addon/assets/glow.material&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="library" tabindex="-1">Write a library <a class="header-anchor" href="#library" aria-label="Permalink to &quot;Write a library {#library}&quot;">​</a></h2><p>A library has one entry point, declared with <a href="/latest/api/cpp/file/src-addon-addon-hpp#atmo-register-addon" class="atmo-ref atmo-ref--symbol"><code>ATMO_REGISTER_ADDON</code></a> and called when the addon is loaded:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;addon/addon.hpp&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;spdlog/spdlog.h&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> namespace</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> atmo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ATMO_REGISTER_ADDON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    spdlog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello world from My Addon!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>api</code>, an <a href="/latest/api/cpp/class/atmo-addon-atmoapi" class="atmo-ref atmo-ref--symbol"><code>AtmoAPI</code></a>, gives access to the engine:</p><table tabindex="0"><thead><tr><th>Member</th><th>Description</th></tr></thead><tbody><tr><td><a href="/latest/api/cpp/class/atmo-addon-atmoapi#engine" class="atmo-ref atmo-ref--symbol"><code>AtmoAPI::engine</code></a></td><td>The engine, with its world</td></tr><tr><td><a href="/latest/api/cpp/class/atmo-addon-atmoapi#input-manager" class="atmo-ref atmo-ref--symbol"><code>AtmoAPI::input_manager</code></a></td><td>Named inputs</td></tr><tr><td><a href="/latest/api/cpp/class/atmo-addon-atmoapi#arg-manager" class="atmo-ref atmo-ref--symbol"><code>AtmoAPI::arg_manager</code></a></td><td>Command-line arguments</td></tr><tr><td><a href="/latest/api/cpp/class/atmo-addon-atmoapi#entity-registry" class="atmo-ref atmo-ref--symbol"><code>AtmoAPI::entity_registry</code></a></td><td>Entity types: see <a href="/latest/manual/adding-entities" class="atmo-ref atmo-ref--page" data-preview="For engine contributors. Declare an entity type and its component, and register them with the engine.">Adding an entity or a component</a></td></tr><tr><td><a href="/latest/api/cpp/class/atmo-addon-atmoapi#subresource-registry" class="atmo-ref atmo-ref--symbol"><code>AtmoAPI::subresource_registry</code></a></td><td>Subresource types, such as physics shapes</td></tr><tr><td><a href="/latest/api/cpp/class/atmo-addon-atmoapi#meta-registry" class="atmo-ref atmo-ref--symbol"><code>AtmoAPI::meta_registry</code></a></td><td>Component types</td></tr><tr><td><a href="/latest/api/cpp/class/atmo-addon-atmoapi#rendering-server" class="atmo-ref atmo-ref--symbol"><code>AtmoAPI::rendering_server</code></a></td><td>Rendering</td></tr></tbody></table><p>Build it with the same compiler and the same version of the source code as the engine. <code>ATMO_DIR</code> is the folder of the engine:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> addons/My_Addon</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ATMO_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/path/to/atmo</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> My_Addon</span></span></code></pre></div><p>The library must be next to <code>addon.json</code>, under the internal name of the addon: <code>My_Addon.so</code> on Linux, <code>My_Addon.dll</code> on Windows and <code>My_Addon.dylib</code> on macOS.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A library runs with all the rights of the engine. Only install addons you trust.</p></div><h2 id="export" tabindex="-1">Exported games <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Exported games {#export}&quot;">​</a></h2><p>Exported games do not load addons at the moment: libraries are not called, and the log says <code>addon.json not found</code>. The assets of addons are packed and can be used.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors {#errors}&quot;">​</a></h2><p>An addon that cannot be loaded is skipped, and the reason is logged:</p><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th></tr></thead><tbody><tr><td><code>addon.json not found</code></td><td>The path in the settings is wrong</td></tr><tr><td><code>ATMO version mismatch</code></td><td><code>atmo_version</code> is not the version of the engine</td></tr><tr><td><code>dlopen failed</code>, <code>LoadLibrary failed</code></td><td>The library is missing, not built, or misses a symbol</td></tr><tr><td><code>Symbol &#39;atmo_register_addon_entrypoint&#39; not found</code></td><td>The library has no <a href="/latest/api/cpp/file/src-addon-addon-hpp#atmo-register-addon" class="atmo-ref atmo-ref--symbol"><code>ATMO_REGISTER_ADDON</code></a></td></tr></tbody></table>`,30)])])}const m=e(d,[["render",n]]);export{k as __pageData,m as default};
